@Test
public void generatedXmlIsValid() throws Exception {
    Document document = readToDocument(xmlAsBytes, true);
    List<String> sources = Arrays.asList("/schema/example.xsd", "/schema/org/apache/aries/blueprint/blueprint.xsd", "/schema/org/apache/aries/blueprint/ext/impl/blueprint-ext.xsd", "/schema/org/apache/aries/blueprint/ext/impl/blueprint-ext-1.1.xsd", "/schema/org/apache/aries/blueprint/ext/impl/blueprint-ext-1.2.xsd", "/schema/org/apache/aries/blueprint/ext/impl/blueprint-ext-1.3.xsd", "/schema/org/apache/aries/blueprint/ext/impl/blueprint-ext-1.4.xsd", "/schema/org/apache/aries/blueprint/ext/impl/blueprint-ext-1.5.xsd", "/schema/org/apache/aries/blueprint/ext/impl/blueprint-ext-1.0.0.xsd", "/schema/org/apache/aries/blueprint/ext/impl/blueprint-ext-1.1.0.xsd", "/schema/org/apache/aries/blueprint/ext/impl/blueprint-ext-1.2.0.xsd", "/schema/org/apache/aries/blueprint/ext/impl/blueprint-ext-1.3.0.xsd", "/schema/org/apache/aries/blueprint/ext/impl/blueprint-ext-1.4.0.xsd", "/schema/org/apache/aries/blueprint/ext/impl/blueprint-ext-1.5.0.xsd", "/schema/org/apache/aries/blueprint/ext/impl/blueprint-ext-1.6.0.xsd", "/schema/org/apache/aries/blueprint/compendium/cm/blueprint-cm-1.0.0.xsd", "/schema/org/apache/aries/blueprint/compendium/cm/blueprint-cm-1.1.0.xsd", "/schema/org/apache/aries/blueprint/compendium/cm/blueprint-cm-1.2.0.xsd", "/schema/org/apache/aries/blueprint/compendium/cm/blueprint-cm-1.3.0.xsd", "/schema/org/apache/aries/blueprint/compendium/cm/blueprint-cm-1.4.0.xsd", "/schema/org/apache/aries/transaction/parsing/transactionv12.xsd", "/schema/org/apache/aries/jpa/blueprint/namespace/jpa_110.xsd");
    List<Source> schemas = new ArrayList<>();
    for (String source : sources) {
        InputStream is = BlueprintFileWriterTest.class.getResourceAsStream(source);
        if (is != null) {
            schemas.add(new StreamSource(is));
        }
    }
    Source xmlFile = new DOMSource(document);
    SchemaFactory schemaFactory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
    Schema schema = schemaFactory.newSchema(schemas.toArray(new Source[schemas.size()]));
    Validator validator = schema.newValidator();
    validator.validate(xmlFile);
}

